# میانگین عددهای فهرست را برمی‌گرداند
def average(nums):
    # جمع را از صفر شروع می‌کنیم
    total = 0
    # هر عدد را به جمع اضافه می‌کنیم
    for x in nums:
        total = total + x
    # جمع را بر تعداد عددها تقسیم می‌کنیم
    return total / len(nums)

